172	// memberList turns the names a group declares into addresses.
173	func memberList(dockerURL string, names []string) []GroupMember {
174		members := make([]GroupMember, 0, len(names))
175		for _, name := range names {
176			url, prefix := memberAddress(dockerURL, name)
177			members = append(members, GroupMember{
178				Alias:      cleanMemberAlias(name),
179				URL:        url,
180				RepoPrefix: prefix,
181			})
182		}
183		return members
184	}
