216	// nexusGET performs an authenticated GET and returns the response body.
217	func (n *NexusDetector) nexusGET(ctx context.Context, endpoint string, info RegistryInfo) ([]byte, error) {
218		req, err := http.NewRequestWithContext(ctx, "GET", endpoint, nil)
219		if err != nil {
220			return nil, err
221		}
222		if info.Username != "" && info.Password != "" {
223			req.SetBasicAuth(info.Username, info.Password)
224		}
225		resp, err := nexusHTTPClient.Do(req)
226		if err != nil {
227			// A refused redirect comes back without the URL it pointed to, which
228			// may be signed.
229			return nil, oci.StripRedirectTarget(err)
230		}
231		defer func() { _ = resp.Body.Close() }()
232		if resp.StatusCode != http.StatusOK {
233			return nil, fmt.Errorf("HTTP %d", resp.StatusCode)
234		}
235		body, err := oci.ReadAllLimited(resp.Body, maxNexusResponse)
236		if err != nil {
237			return nil, fmt.Errorf("read Nexus response: %w", err)
238		}
239		return body, nil
240	}
